-- texts the script shows itself, per language (lang/<code>.txt, script.<name>); every language has every key
M.texts = {
    en = { ko_suffix = "(KO)" },
    ru = { ko_suffix = "(без сознания)" },
    zh = { ko_suffix = "（昏迷）" },
}

-- settings.cfg in the game folder holds language=zh_CN; the first two letters pick the texts, English otherwise
local function gameLanguage()
    local f = io.open("settings.cfg", "r")
    if not f then return "en" end
    local cfg = f:read("*a")
    f:close()
    local lang = cfg:match("^language=(%a+)") or cfg:match("\nlanguage=(%a+)")
    if lang == nil then return "en" end
    lang = lang:lower():sub(1, 2)
    if M.texts[lang] == nil then return "en" end
    return lang
end

local textLang = nil
function M.text(name)
    if textLang == nil then textLang = gameLanguage() end
    local t = M.texts[textLang][name]
    if t == nil then error("no text " .. tostring(name) .. " in " .. textLang) end
    return t
end

local DLL = "PoshNameplatesMCM.dll"
local INI = "Nameplates.ini"
local FOLDER = "Nameplates"
local WORKSHOP_ID = "3822135808"

local ffi = nil
do
    local ok, f = pcall(require, "ffi")
    if ok then ffi = f end
end

-- private names (asm aliases), so other scripts declaring the same Windows functions do not collide
local fnPath, fnVersion = nil, nil
local function bindPlugin()
    if fnVersion then return true end
    if ffi == nil then return false end
    pcall(ffi.cdef, [[
        void* np_settings_GetModuleHandleA(const char* name) __asm__("GetModuleHandleA");
        void* np_settings_GetProcAddress(void* module, const char* name) __asm__("GetProcAddress");
    ]])
    local ok = pcall(function()
        local h = ffi.C.np_settings_GetModuleHandleA(DLL)
        if h == nil then error("plugin not loaded") end
        local p = ffi.C.np_settings_GetProcAddress(h, "Posh_IniPath")
        local v = ffi.C.np_settings_GetProcAddress(h, "Posh_SettingsVersion")
        if p == nil or v == nil then error("plugin exports missing") end
        fnPath = ffi.cast("const char* (*)(void)", p)
        fnVersion = ffi.cast("int (*)(void)", v)
    end)
    return ok
end

-- The ini lives next to the plugin. KenshiLua runs this script as soon as it is loaded itself, so a plugin
-- further down the load order is not loaded yet: the ini is then looked for where the plugin will be, in the
-- local mod folder or in this mod's Workshop folder (the game runs from the Kenshi folder).
local function folderIni()
    local tries = { "mods/" .. FOLDER .. "/" .. INI, "../../workshop/content/233860/" .. WORKSHOP_ID .. "/" .. INI }
    for _, p in ipairs(tries) do
        local f = io.open(p, "r")
        if f then
            f:close()
            return p
        end
    end
    return tries[1]
end

function M.iniPath()
    if bindPlugin() then
        local ok, p = pcall(function() return ffi.string(fnPath()) end)
        if ok and p ~= "" then return p end
    end
    return folderIni()
end

local function readIni(path)
    local f = io.open(path, "r")
    if not f then return nil end
    local text = f:read("*a")
    f:close()
    local values, inSection = {}, false
    for line in text:gmatch("[^\r\n]+") do
        local sec = line:match("^%s*%[(.-)%]%s*$")
        if sec then
            inSection = sec == M.section
        elseif inSection then
            local k, v = line:match("^%s*([^=;]-)%s*=%s*(.-)%s*$")
            if k and k ~= "" then values[k] = v end
        end
    end
    return values
end

local function colourOf(text)
    local r, g, b = text:match("^#?(%x%x)(%x%x)(%x%x)$")
    if r == nil then return nil end
    return { tonumber(r, 16) / 255, tonumber(g, 16) / 255, tonumber(b, 16) / 255 }
end

local function convert(item, raw)
    if raw == nil then
        if item.kind == "colour" then return colourOf(item.default) end
        return item.default
    end
    raw = raw:gsub("%s*;.*$", "")                    -- a trailing "; comment"
    local kind = item.kind
    if kind == "bool" then
        local low = raw:lower()
        if raw == "1" or low == "true" then return true end
        if raw == "0" or low == "false" then return false end
        return item.default
    elseif kind == "int" or kind == "float" then
        local n = tonumber(raw)
        if n == nil then return item.default end
        if kind == "int" then n = math.floor(n + 0.5) end
        return math.max(item.lo, math.min(item.hi, n))
    elseif kind == "choice" then
        for _, v in ipairs(item.values) do
            if v == raw then return v end
        end
        return item.default
    elseif kind == "colour" then
        return colourOf(raw) or colourOf(item.default)
    end
    error("unknown setting kind " .. tostring(kind))
end

local function same(a, b)
    if type(a) == "table" and type(b) == "table" then
        return math.abs(a[1] - b[1]) < 1e-4 and math.abs(a[2] - b[2]) < 1e-4 and math.abs(a[3] - b[3]) < 1e-4
    end
    return a == b
end

-- Reads the ini into the given tables (roots = { CONFIG = ..., COLOURS = ... }).
-- Returns the keys whose value changed and whether the ini file exists.
function M.apply(roots)
    local values = readIni(M.iniPath())
    local changed = {}
    for _, item in ipairs(M.items) do
        local v = convert(item, values and values[item.key])
        local t = roots[item.root]
        for i = 1, #item.path - 1 do t = t[item.path[i]] end
        local last = item.path[#item.path]
        if not same(t[last], v) then
            t[last] = v
            changed[#changed + 1] = item.key
        end
    end
    return changed, values ~= nil
end

-- Call every frame; returns the changed keys right after MCM changed something, otherwise nil.
local lastVersion, timer = nil, 0
function M.poll(dt, roots)
    timer = timer - dt
    if timer > 0 then return nil end
    timer = 0.5
    if not bindPlugin() then return nil end
    local ok, v = pcall(function() return fnVersion() end)
    if not ok then return nil end
    if lastVersion == nil then
        -- the plugin has just been found: read its ini again, the first read may have come before it loaded
        lastVersion = v
        return (M.apply(roots))
    end
    if v == lastVersion then return nil end
    lastVersion = v
    return (M.apply(roots))
end

function M.pluginLoaded() return bindPlugin() end

return M
